// AddUrlForwardRequest defines model for AddUrlForwardRequest.
type AddUrlForwardRequest struct {
	Apikey string `json:"apikey"`

	// IncludePath Whether to append the request URI path to the forwarding destination
	IncludePath AddUrlForwardRequestIncludePath `json:"includePath"`

	// Location Destination URL to forward to
	//
	// Example: https://destination.example.com
	Location string `json:"location"`

	// RedirectType Optional. The exact redirect type; takes precedence over `type` when supplied. 301 = permanent, 302 or 307 = temporary (this is how you request 307), masked = URL masking. Omit to derive from `type` (temporary->302, permanent->301).
	//
	// Example: 307
	RedirectType *AddUrlForwardRequestRedirectType `json:"redirectType,omitempty"`
	Secretapikey string                            `json:"secretapikey"`

	// Subdomain Subdomain to forward (optional, leave blank or omit for root domain). Alphanumeric and hyphens only.
	//
	// Example: www
	Subdomain *string `json:"subdomain,omitempty"`

	// Type Redirect kind. 'permanent' = HTTP 301; 'temporary' = HTTP 302 (default); 'masked' = loads the destination in a frame (URL masking). For a precise code — including a 307 temporary redirect — use `redirectType`.
	Type AddUrlForwardRequestType `json:"type"`

	// Wildcard Whether to also forward all subdomains of the forwarded subdomain
	Wildcard AddUrlForwardRequestWildcard `json:"wildcard"`
}

